package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;
import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
import org.springframework.samples.petclinic.rest.escalation.DuplicateIdentityException;

/**
 * The single duplicate-detection step in the create-owner pipeline, consolidating what used to be
 * separate telephone, email and household checks. Runs after the telephone and email are normalized
 * and after {@link DeriveHouseholdId} has resolved any shared {@code householdId}.
 *
 * <p>It derives the request's {@code identityKey} exactly as {@link Owner#getIdentityKey()} does —
 * {@code normalizedTelephone|email|householdId} (email and householdId empty when absent) — and
 * rejects with a 409 only when the WHOLE key equals an existing owner's. Because the telephone is
 * part of the key, two members of the same household (same {@code householdId}) with different
 * telephones have different identityKeys and are both allowed; only an exact full-key match is a
 * duplicate.
 */
public class EnsureUniqueIdentity {

    public void service(@Val OwnerFieldsDto request, @Val HouseholdId householdId,
            OwnerRepository ownerRepository) throws DuplicateIdentityException {
        String householdIdValue = (householdId == null) ? null : householdId.value();
        String identityKey = identityKey(request, householdIdValue);
        for (Owner existing : ownerRepository.findAll()) {
            if (identityKey.equals(existing.getIdentityKey())) {
                throw new DuplicateIdentityException(identityKey);
            }
        }
    }

    /** Derive the key for the owner being created, matching {@link Owner#getIdentityKey()} exactly. */
    private static String identityKey(OwnerFieldsDto request, String householdId) {
        String tel = request.getTelephone() == null ? "" : request.getTelephone();
        String email = request.getEmail();
        String mail = (email == null || email.isBlank()) ? "" : email;
        String household = (householdId == null || householdId.isBlank()) ? "" : householdId;
        return tel + "|" + mail + "|" + household;
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;

/**
 * Runs in the create-owner pipeline after {@link BuildOwner}. Stamps the shared household identifier
 * derived by {@link EnsureUniqueHousehold} onto the owner being created so it is stored and returned.
 * When the request did not join an existing household the identifier is {@code null} and the owner
 * keeps none.
 */
public class AssignHousehold {

    public void service(@Val Owner owner, @Val HouseholdId householdId) {
        if (householdId != null && householdId.value() != null) {
            owner.setHouseholdId(householdId.value());
        }
    }
}

package org.springframework.samples.petclinic.rest.function.owner;

import net.officefloor.plugin.variable.Val;
import org.springframework.samples.petclinic.model.Owner;
import org.springframework.samples.petclinic.repository.OwnerRepository;

/**
 * Soft-match step in the create-owner pipeline. Runs after {@link BuildOwner} (so the owner carries
 * its normalized telephone, lastName and postcode) and before {@link SaveOwner}. It is reached only
 * for owners that already passed {@link EnsureUniqueIdentity}, i.e. that are NOT hard duplicates.
 *
 * <p>An owner is a <em>possible</em> duplicate when an existing owner shares its {@code lastName}
 * and {@code postcode} but has a different {@code telephone}. When such an owner exists the new
 * owner is still created, but flagged with {@code possibleDuplicate = true} and
 * {@code possibleDuplicateOf} set to the matching owner's id (the lowest id when several match).
 * Otherwise {@code possibleDuplicate} is set to {@code false} and no match id is recorded.
 */
public class DetectPossibleDuplicate {

    public void service(@Val Owner owner, OwnerRepository ownerRepository) {
        owner.setPossibleDuplicate(false);
        owner.setPossibleDuplicateOf(null);

        String lastName = owner.getLastName();
        String postcode = owner.getPostcode();
        String telephone = owner.getTelephone();
        if (lastName == null || postcode == null || postcode.isBlank()) {
            return; // a shared lastName+postcode is required to be a possible duplicate
        }

        Integer matchId = null;
        for (Owner existing : ownerRepository.findAll()) {
            if (existing.getId() == null) {
                continue;
            }
            if (lastName.equals(existing.getLastName())
                    && postcode.equals(existing.getPostcode())
                    && !equalsTelephone(telephone, existing.getTelephone())) {
                if (matchId == null || existing.getId() < matchId) {
                    matchId = existing.getId();
                }
            }
        }

        if (matchId != null) {
            owner.setPossibleDuplicate(true);
            owner.setPossibleDuplicateOf(matchId);
        }
    }

    private static boolean equalsTelephone(String a, String b) {
        return a == null ? b == null : a.equals(b);
    }
}

